"""torch4ms adapter for the Section 6.6 bridge-safe causal LM."""
import torch
import torch.nn as nn
import torch.optim as optim

import torch4ms
from torch4ms.autograd.ms_autograd_function import extract_and_wrap_loss_fn
from torch4ms.optim import Torch4msOptimizer


class PocketCausalLM(nn.Module):
    def __init__(self, vocab=80, width=32):
        super().__init__()
        self.token_emb = nn.Embedding(vocab, width)
        self.proj = nn.Linear(width, width)
        self.act = nn.ReLU()
        self.lm_head = nn.Linear(width, vocab)

    def forward(self, tokens):
        hidden = self.act(self.proj(self.token_emb(tokens)))
        return self.lm_head(hidden)


class _SequenceCrossEntropyLoss(nn.Module):
    def forward(self, logits, targets):
        return nn.functional.cross_entropy(
            logits.reshape(-1, logits.shape[-1]),
            targets.reshape(-1),
        )


def build_model(params=None):
    return PocketCausalLM()


def train_one_step(model, x, y, lr=1e-3):
    criterion = _SequenceCrossEntropyLoss()
    base_optimizer = optim.SGD(model.parameters(), lr=lr)
    optimizer = Torch4msOptimizer(base_optimizer, model)
    env = torch4ms.default_env()
    with env:
        optimizer.zero_grad()
        loss_wrapper = extract_and_wrap_loss_fn(
            model, criterion, x, y
        )
        loss = loss_wrapper.output
        loss.backward(module=model)
        optimizer.step()
        return float(loss.detach().item())

